from __future__ import annotations
from html import escape

def render_public_page(uuid_key: str, logo_url: str) -> str:
    key=escape(uuid_key,quote=True); logo=escape(logo_url,quote=True)
    return f'''<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#000000"><title>اشتراک FineVPN</title><link rel="stylesheet" href="/assets/app.css"></head><body class="public-body"><header class="public-nav"><img src="{logo}" class="brand-logo"><b>FineVPN</b><span class="push"></span><span class="muted">پنل اشتراک</span></header><main class="public-wrap"><section class="card public-hero"><div class="row"><div><div class="eyebrow">FINEVPN · SUBSCRIPTION</div><h1 id="sub-name">در حال بارگذاری اشتراک</h1><p class="muted" id="sub-desc">وضعیت سرویس و کانفیگ‌های شما</p></div><span class="status-pill" id="sub-status">در حال بررسی</span></div><div id="locked" class="hidden"><p>این اشتراک با رمز محافظت شده است.</p><input id="sub-password" type="password" placeholder="رمز اشتراک"><button class="btn red" onclick="loadSub()">باز کردن اشتراک</button></div><div id="sub-content"><div class="grid four" id="sub-metrics"></div><div class="usage-wrap"><div class="row between"><b>مصرف حجم</b><b id="usage-label">—</b></div><div class="progress"><span id="usage-bar"></span></div></div><div class="row between section-head"><h2>کانفیگ‌های شما</h2><a class="btn red" id="download-all" href="/sub-group/{key}">دانلود اشتراک</a></div><div id="config-list" class="config-list"></div></div></section><footer class="public-foot">FineVPN · اتصال پایدار، مدیریت شفاف</footer></main><script>const SUB_KEY='{key}';</script><script src="/assets/public.js"></script></body></html>'''
